"""Verify release notes generated by the workspace's release-notes skill."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

APPLICATION = Path("/app")
SOURCE_FILE = APPLICATION / "release_data.json"
OUTPUT_FILE = APPLICATION / "RELEASE_NOTES.md"


def expected_release_notes() -> str:
    """Build the required Markdown from the immutable release input."""
    data = json.loads(SOURCE_FILE.read_text())
    sections = (("added", "Added"), ("changed", "Changed"), ("fixed", "Fixed"))
    parts = [f"# {data['product']} {data['version']}"]

    for kind, title in sections:
        changes = sorted(
            (
                change
                for change in data["changes"]
                if change["customer_visible"] and change["kind"] == kind
            ),
            key=lambda change: change["issue"],
        )
        if changes:
            bullets = "\n".join(f"- [#{change['issue']}] {change['summary']}" for change in changes)
            parts.append(f"## {title}\n{bullets}")

    return "\n\n".join(parts) + "\n"


def test_release_data_is_unchanged() -> None:
    expected_digest = "3843f2f565c2e6aa990a4bf17fdb1d90489799dea94c7a77b58a959b74e755fb"

    assert hashlib.sha256(SOURCE_FILE.read_bytes()).hexdigest() == expected_digest


def test_release_notes_match_the_skill_output_exactly() -> None:
    assert OUTPUT_FILE.is_file()
    assert OUTPUT_FILE.read_text() == expected_release_notes()


def test_only_the_required_release_notes_artifact_was_added() -> None:
    assert sorted(path.name for path in APPLICATION.iterdir()) == [
        "RELEASE_NOTES.md",
        "release_data.json",
        "skills",
    ]
